19	namespace bg = boost::geometry;
20	
21	bool PlanView::add_line(geometry::Point2d start_point, float heading, float length) {
22	  //! straight line
23	  reference_line_.add_point(start_point);
24	  geometry::Point2d end_point(bg::get<0>(start_point) + length * cos(heading), bg::get<1>(start_point) + length * sin(heading));
25	  reference_line_.add_point(end_point);
26	
27	  //! calculate overall length
28	  length_ = bg::length(reference_line_.obj_);
29	  return true;
30	}
31	
32	bool PlanView::add_spiral(geometry::Point2d start_point, float heading, float length, float curvature_start, float curvature_end, float s_inc) {
33	  double x = bg::get<0>(start_point), y = bg::get<1>(start_point), t = heading, cDot = (curvature_end - curvature_start) / length;
34	  double x_old = bg::get<0>(start_point), y_old = bg::get<1>(start_point);
35	
36	  double s = 0.0;
37	  for (; s < length; s += s_inc) {
38	    odrSpiral(s, x_old, y_old, cDot, curvature_start, heading, &x, &y, &t);
39	    reference_line_.add_point(geometry::Point2d(x, y));
40	  }
41	
42	  // fill last point if increment does not match
43	  double delta_s = fabs(length - s);
44	  if (delta_s > 0.0) {
45	    odrSpiral(length, x_old, y_old, cDot, curvature_start, heading, &x, &y, &t);
46	    reference_line_.add_point(geometry::Point2d(x, y));
47	  }
48	  
49	  length_ = bg::length(reference_line_.obj_);
50	  return true;
51	}
52	
53	void PlanView::calc_arc_position(const float s, float initial_heading, float curvature, float &dx, float &dy) {
54	  initial_heading = fmod(initial_heading, 2 * M_PI);
55	  float hdg = initial_heading - M_PI / 2;
56	
57	  float a = 2 / curvature * sin(s * curvature / 2);
58	  float alpha = (M_PI - s * curvature) / 2 - hdg;
59	
60	  dx = -1 * a * cos(alpha);
61	  dy = a * sin(alpha);
62	
63	  // tangent = initial_heading + s * initial_curvature;
64	}
65	
66	bool PlanView::add_arc(geometry::Point2d start_point, float heading, float length, float curvature, float s_inc) {
67	  // add_spiral(start_point, heading, length, curvature, curvature, s_inc);
68	
69	  float dx, dy;
70	  double x_old = bg::get<0>(start_point), y_old = bg::get<1>(start_point);
71	  double s = 0.0;
72	  for (; s < length; s += s_inc) {
73	    calc_arc_position(s, heading, curvature, dx, dy);
74	    reference_line_.add_point(geometry::Point2d(x_old + dx, y_old + dy));
75	  }
76	  
77	  // fill last point if increment does not match
78	  double delta_s = fabs(length - s);
79	  if (delta_s >= 0.0){
80	    calc_arc_position(length, heading, curvature, dx, dy);
81	    reference_line_.add_point(geometry::Point2d(x_old + dx, y_old + dy));
82	  }
83	  
84	  return true;
85	}
86	
87	geometry::Line PlanView::create_line(int id, LaneWidth lane_width, float s_inc) {
88	  float s_start = lane_width.s_start;
89	  float s_end = lane_width.s_end;
90	  LaneOffset off = lane_width.off;
91	
92	  float s = s_start;
93	  float scale = 0.0f;
94	  geometry::Line tmp_line;
95	  geometry::Point2d normal(0.0f, 0.0f);
96	  int sign = id > 0 ? -1 : 1;
97	
98	  // TODO(fortiss): check if sampling does work with relative s, probably not
99	  if (off.b != 0.0f || off.c != 0.0f || off.d != 0.0f || (lane_width.s_end - lane_width.s_start) != 1.0) {
100	    for (; s < s_end; s += s_inc) {
101	      geometry::Point2d point = get_point_at_s(reference_line_, s);
102	      normal = get_normal_at_s(reference_line_, s);
103	      scale = -sign * polynom(s, off.a, off.b, off.c, off.d);
104	      tmp_line.add_point(geometry::Point2d(bg::get<0>(point) + scale * bg::get<0>(normal),
105	                                  bg::get<1>(point) + scale * bg::get<1>(normal)));
106	    }
107	
108	    // fill last point if increment does not match
109	    double delta_s = fabs(s_end-s);
110	    if(delta_s>0.0){
111	      geometry::Point2d point = get_point_at_s(reference_line_, s_end);
112	      normal = get_normal_at_s(reference_line_, s_end);
113	      scale = -sign * polynom(s_end, off.a, off.b, off.c, off.d);
114	      tmp_line.add_point(geometry::Point2d(bg::get<0>(point) + scale * bg::get<0>(normal),
115	                                  bg::get<1>(point) + scale * bg::get<1>(normal)));
116	    }
117	  } else {
118	      for (uint32_t i = 0; i < reference_line_.obj_.size() - 1; i++) {
119	        normal = get_normal_at_s(reference_line_, reference_line_.s_[i]);
120	        scale = -sign * polynom(s, off.a, off.b, off.c, off.d);
121	        tmp_line.add_point(geometry::Point2d(bg::get<0>(reference_line_.obj_[i]) + scale * bg::get<0>(normal),
122	                                  bg::get<1>(reference_line_.obj_[i]) + scale * bg::get<1>(normal)));
123	        s += geometry::distance(reference_line_.obj_[i + 1], reference_line_.obj_[i]);
124	      }
125	      // add last point
126	      normal = get_normal_at_s(reference_line_, reference_line_.s_[reference_line_.obj_.size() - 1]);
127	      int size = reference_line_.obj_.size() - 1;
128	      scale = -sign * polynom(length_, off.a, off.b, off.c, off.d);
129	      tmp_line.add_point(geometry::Point2d(bg::get<0>(reference_line_.obj_[size]) + scale * bg::get<0>(normal),
130	                                bg::get<1>(reference_line_.obj_[size]) + scale * bg::get<1>(normal)));
131	  }
132	
133	
134	  return tmp_line;
135	}
