65	    using boost::geometry::append;
66	    // Get first and last point
67	    auto last_point_this = Shape<bg::model::linestring<T>, T>::obj_[Shape<bg::model::linestring<T>, T>::obj_.size() - 1];
68	    auto first_point_other = other_line.obj_[0];
69	    auto last_point_other = other_line.obj_[other_line.obj_.size() - 1];
70	    float distance_last_last = distance(last_point_this, last_point_other);
71	    float distance_last_first = distance(last_point_this, first_point_other);
72	
73	    //std::cout << distance_last_last << " - " << distance_last_first << std::endl;
74	    if (distance_last_last> distance_last_first) {
75	      append_linestring(other_line);
76	    } else {
77	      //std::cout << "REVERSING" << std::endl;
78	      Line_t new_line = other_line;
