94	  bool recompute_s() {
95	    s_.clear();
96	    // edge case no points
97	    if (Shape<bg::model::linestring<T>, T>::obj_.empty()) {
98	      return true;
99	
100	    } else if (Shape<bg::model::linestring<T>, T>::obj_.size() == 1) {  // edge case one point
101	      s_.push_back(0.0);
102	      return true;
103	    } else {  // nominal case
104	      // compute distance from last point to next point and store these on vector s_ (avoid additional tmp vector)
105	      T last_pt = Shape<bg::model::linestring<T>, T>::obj_.front();
106	      s_.reserve(Shape<bg::model::linestring<T>, T>::obj_.size());
107	      double distance_until_now = 0.0;
108	      for (const T &next_pt : Shape<bg::model::linestring<T>, T>::obj_) {
109	        distance_until_now += bg::distance(next_pt, last_pt);
110	        s_.push_back(distance_until_now);
111	        last_pt = next_pt;
112	      }
113	      // // divide by total distance --> s \in 0..1
114	      // const double &last_s = s_.back();
115	      // for (int i = 0; i < s_.size(); ++i) {  // normalized 0..1
116	      //   s_[i] = s_[i] / last_s;
117	      // }
118	      return true;
119	    }
