//! Creates a lane by offsetting the given reference line (previous_line) by the
//! width polynom of lane_width_current. Decouples lane creation from the plan
//! view so that outer lanes can be offset from any (inner) reference line.
inline std::shared_ptr<Lane> create_lane_from_lane_width(
    LanePosition lane_position,
    geometry::Line previous_line,
    LaneWidth lane_width_current,
    float s_inc = 0.5f) {
  namespace bg = boost::geometry;
  std::shared_ptr<Lane> ret_lane(new Lane(lane_position));

  float s_start = lane_width_current.s_start;
  float s_end = lane_width_current.s_end;
  LaneOffset off = lane_width_current.off;

  float scale = 0.0f;
  geometry::Line tmp_line;
  geometry::Point2d normal(0.0f, 0.0f);
  int sign = lane_position > 0 ? -1 : 1;

  float s = s_start;
  for (; s < s_end; s += s_inc) {
    geometry::Point2d point = get_point_at_s(previous_line, s);
    normal = get_normal_at_s(previous_line, s);
    scale = -sign * polynom(s, off.a, off.b, off.c, off.d);
    tmp_line.add_point(
        geometry::Point2d(bg::get<0>(point) + scale * bg::get<0>(normal),
                          bg::get<1>(point) + scale * bg::get<1>(normal)));
  }

  // fill last point if increment does not match
  double delta_s = fabs(s_end - s);
  if (delta_s > 0.0) {
    geometry::Point2d point = get_point_at_s(previous_line, s_end);
    normal = get_normal_at_s(previous_line, s_end);
    scale = -sign * polynom(s_end, off.a, off.b, off.c, off.d);
    tmp_line.add_point(
        geometry::Point2d(bg::get<0>(point) + scale * bg::get<0>(normal),
                          bg::get<1>(point) + scale * bg::get<1>(normal)));
  }

  ret_lane->set_line(tmp_line);
  return ret_lane;
